window.StrictDoc.search.nodesByMid = {"1":{"MID":"ce36ec4d6b6c4f27a0c00567c4fdd0ae","UID":"IA-IRS-001","STATUS":"Active","TITLE":"Public package imports","STATEMENT":"The following imports SHALL succeed after editable install:\n\n  import ironair\n  from ironair import constants\n  from ironair import chemistry\n  from ironair import components\n  from ironair import simulation\n  from ironair import scenarios\n  from ironair import plotting\n","COMMENT":"tests/test_package_imports.py passes in the project virtual environment.\n","_LINK":"IA-IRS-001"},"2":{"MID":"d66e1884a3fc4fdb8aeff87b645aff1d","UID":"IA-IRS-002","STATUS":"Active","TITLE":"RHS signature","STATEMENT":"Every dynamic component SHALL expose:\n\n  def rhs(self, t, y, inputs, context) -> numpy.ndarray\n\nt is time in seconds, y is a 1-D float64 state vector, inputs is a mapping of named\nphysical inputs, and context carries shared couplings without hidden mutation of\ncomponent parameters.\n","COMMENT":"Signature inspection and a deterministic double-evaluation test pass for each component.\n","_LINK":"IA-IRS-002"},"3":{"MID":"7f91f82f3b4747aeac505c99dae00a52","UID":"IA-IRS-003","STATUS":"Active","TITLE":"CoupledSystem simulate interface","STATEMENT":"ironair.simulation.CoupledSystem.simulate SHALL accept t_span, optional t_eval,\noptional inputs callable, solver method, and tolerances, and SHALL return a\nSimulationResult.\n","COMMENT":"Default method is BDF or Radau. Result includes t, y, state_names, and diagnostics.\n","_LINK":"IA-IRS-003"},"4":{"MID":"3760feb94d084fa99e4292038f8bb6c6","UID":"IA-IRS-004","STATUS":"Active","TITLE":"Plotting input types","STATEMENT":"ironair.plotting functions SHALL accept SimulationResult or pandas.DataFrame.\n","COMMENT":"Both input types produce a matplotlib Figure.\n","_LINK":"IA-IRS-004"},"5":{"MID":"ba0399333c3642428acb1182d993c85d","UID":"IA-IRS-005","STATUS":"Active","TITLE":"Estimator measurement-only interface","STATEMENT":"BatteryStateEstimator SHALL accept measurements and prior estimates only. It SHALL\nNOT receive the plant hidden state vector during observer execution.\n","COMMENT":"Type hints and tests pass a MeasurementVector, not the plant y, into the estimator.\n","_LINK":"IA-IRS-005"},"6":{"MID":"cccd6b911a1746468512a8b6d270257b","UID":"IA-SDD-001","STATUS":"Active","TITLE":"Source layout","STATEMENT":"Package sources SHALL live under src/ironair as specified by IA-SYS-001.\n\nThis SDRS src/ layout is the project-specific design and SHALL be used even though\na generic Cursor rule discourages src/ layouts.\n","COMMENT":"pyproject.toml configures setuptools package discovery with where = [\"src\"].\n","_LINK":"IA-SDD-001"},"7":{"MID":"f8d4d4fff61643079a0c88e7c36e3775","UID":"IA-SDD-002","STATUS":"Active","TITLE":"Dynamic component base","STATEMENT":"All physical components SHALL implement ironair.ode.protocol.DynamicComponentProtocol\nand MAY inherit ironair.ode.component.DynamicComponent for shared validation.\n\nrhs(t, y, inputs, context) SHALL be a pure function of its arguments for a fixed\nparameter configuration.\n","COMMENT":"Protocol checks and unit tests cover every registered component class.\n","_LINK":"IA-SDD-002"},"8":{"MID":"7698c1751ec1461080557ad23aa81d94","UID":"IA-SDD-003","STATUS":"Active","TITLE":"Shared chemistry ownership","STATEMENT":"Electrode components SHALL obtain stoichiometric rates from ironair.chemistry rather\nthan embedding a second reaction network.\n","COMMENT":"Iron, ORR, OER, and HER rate mapping uses ReactionNetwork.S and Faraday conversion.\n","_LINK":"IA-SDD-003"},"9":{"MID":"b165bbf332074345b902becac75972c9","UID":"IA-SDD-004","STATUS":"Active","TITLE":"Algebraic versus dynamic states","STATEMENT":"Instantaneous constitutive laws (Ohmic drop, hydraulic orifice flow at a fixed\nposition, Nernst potential) SHALL be algebraic.\n\nDynamic states SHALL represent stored mass, charge, thermal energy, momentum, or\nexplicit controller memory.\n\nArtificial lag SHALL NOT be added to algebraic laws.\n","COMMENT":"CurrentCollector resistance is algebraic. CurrentCollector temperature is dynamic.\n","_LINK":"IA-SDD-004"},"10":{"MID":"215b2adb7db4497ba3d6b2bf39515177","UID":"IA-SDD-005","STATUS":"Active","TITLE":"Clean Python baseline","STATEMENT":"This Python package is a new baseline. It SHALL NOT import, translate, or recover\ngoverning equations from prior MATLAB or Simulink implementations.\n","COMMENT":"Source tree contains no .m or .slx physics. Chemistry and component modules implement\nthe SDRS reaction set and ODE protocol directly.\n","_LINK":"IA-SDD-005"},"11":{"MID":"4fba50c59dd1449494fe3dce40b38b38","UID":"IA-SYS-001","STATUS":"Active","TITLE":"Python package","STATEMENT":"The software SHALL be implemented as an installable Python package named ironair.\n\nAll public APIs SHALL be importable using:\n\n  import ironair\n  from ironair import constants\n  from ironair import chemistry\n  from ironair import components\n  from ironair import simulation\n  from ironair import scenarios\n  from ironair import plotting\n\nThe implementation SHALL use a standard src/ package layout.\n\nThe project SHALL provide editable installation using:\n\n  pip install -e \".[dev,notebooks]\"\n","RATIONALE":"A single installable package is the integration boundary for notebooks, tests, and coupled simulation.\nThe SDRS src/ layout takes precedence over the generic no-src-directory Cursor rule for this project.\n","COMMENT":"Package ironair installs in a virtual environment. The listed imports succeed after\npip install -e \".[dev,notebooks]\" or the equivalent uv installation.\n","_LINK":"IA-SYS-001"},"12":{"MID":"d118df3148ff41a7a982f6ba871599f5","UID":"IA-SYS-002","STATUS":"Active","TITLE":"Integrated physics simulation","STATEMENT":"The software SHALL model the complete iron-air battery as a coupled multiphysics system.\n\nThe model SHALL include metallic iron electrode, iron hydroxide and oxide phases,\noxygen reduction electrode, oxygen evolution electrode, hydrogen evolution, alkaline\nelectrolyte, electrolyte transport, separator, gas diffusion layer, current collectors,\ncell assembly, thermal system, air intake, fan/blower, gas manifolds, ventilation,\nelectrolyte reservoir, circulation pump, piping, valves, heat exchanger, battery stack,\nbattery module, battery enclosure, DC electrical distribution, DC/DC conversion, grid\ninverter, transformer, grid interface, measurement sensors, battery management,\nsupervisory control, fault management, state estimation, and degradation and aging.\n\nThese components SHALL interact through shared physical quantities and conserved\nmaterial, charge, and energy flows.\n","RATIONALE":"Balance-of-plant and grid interfaces determine operating envelopes of the electrochemical cell.\n","COMMENT":"Every listed component has a DynamicComponent implementation that can be assembled into\nironair.simulation.CoupledSystem and exchanges named physical flows.\n","_LINK":"IA-SYS-002"},"13":{"MID":"eae36b11e5d9479abe9adad73ab2de96","UID":"IA-SYS-003","STATUS":"Active","TITLE":"ODE-based components","STATEMENT":"Every physical component SHALL expose a dynamic ODE model.\n\nEach component SHALL explicitly define: state vector, state units, initial conditions,\ninput variables, output variables, governing differential equations, algebraic constitutive\nrelations, physical parameters, boundary conditions, conservation residuals, numerical\nconstraints, and associated StrictDoc requirement IDs.\n\nEvery component SHALL provide a rhs() method returning state derivatives.\n\nThe generic mathematical representation SHALL be:\n\n  dx/dt = f(t, x, inputs, parameters)\n\nWhere required:\n\n  0 = g(t, x, algebraic_variables, inputs, parameters)\n\nAlgebraic variables SHALL be solved consistently during RHS evaluation or through a\nsupported DAE backend.\n\nAn artificial time constant SHALL NOT be introduced solely to make an instantaneous\nphysical relation appear dynamic.\n\nPassive structures, such as current collectors, SHALL possess actual dynamic states\nwhere justified, such as temperature. Their instantaneous electrical resistance SHALL\nremain an algebraic relation.\n","COMMENT":"Every DynamicComponent publishes StateSpec metadata and a deterministic rhs(t, y, inputs, context).\nAlgebraic electrical resistance is not converted into a fake lag state.\n","_LINK":"IA-SYS-003"},"14":{"MID":"17c565ad73df493d9b046fb53874b746","UID":"IA-SYS-004","STATUS":"Active","TITLE":"Shared component models","STATEMENT":"Individual component simulations and the integrated battery SHALL use the same implementation.\n\nThe system SHALL NOT contain separate, simplified physics solely for Jupyter examples.\n\nReduced-order versions MAY be implemented, but SHALL be explicitly identified and tested\nagainst the corresponding higher-fidelity models.\n","COMMENT":"Notebooks import ironair and do not define replacement governing equations for production physics.\nReduced-order models are named with a reduced_order flag or class name and have comparison tests.\n","_LINK":"IA-SYS-004"},"15":{"MID":"b82fb501cbd44215bfc7ecbc0790ae18","UID":"IA-SYS-005","STATUS":"Active","TITLE":"Simulation fidelity","STATEMENT":"The software SHALL support lumped ODE models, spatially discretized ODE models,\ncoupled differential-algebraic models, reduced-order dynamic models, and fully\nintegrated system simulations.\n\nSpatially distributed PDE formulations SHALL be discretized using finite-volume or\nfinite-difference methods to produce systems of ODEs or DAEs.\n","COMMENT":"CoupledSystem accepts lumped and spatially discretized components. Spatial components\ndocument their discretization method and node count.\n","_LINK":"IA-SYS-005"},"16":{"MID":"09f38fed7cc34a99bbcb9e9be69fef1c","UID":"IA-REQ-001","STATUS":"Active","TITLE":"StrictDoc source of truth","STATEMENT":"All requirements SHALL be maintained in StrictDoc .sdoc files.\n\nMarkdown SHALL be used for supplementary explanatory design documents but SHALL NOT\nreplace the authoritative requirements database.\n","COMMENT":"Every IA-* UID exists in reqs/**/*.sdoc. CI fails if a source @relation UID is missing\nfrom the StrictDoc database.\n","_LINK":"IA-REQ-001"},"17":{"MID":"8828cb0aec12480a8e1383d11534e604","UID":"IA-REQ-002","STATUS":"Active","TITLE":"Requirement identifiers","STATEMENT":"Each requirement SHALL possess a permanent unique ID.\n\nRequired prefixes: IA-SYS, IA-REQ, IA-CON, IA-CHM, IA-FE, IA-HER, IA-ORR, IA-OER,\nIA-GDL, IA-ELY, IA-SEP, IA-COL, IA-CEL, IA-THM, IA-AIR, IA-FLD, IA-HEX, IA-STK,\nIA-MOD, IA-ENC, IA-DC, IA-CNV, IA-INV, IA-TRF, IA-GRD, IA-CTL, IA-EST, IA-DEG,\nIA-FLT, IA-ODE, IA-NBK, IA-PLT, IA-TST, IA-DOC.\n","COMMENT":"UID uniqueness is verified by tests. All required prefixes appear in the requirements tree.\n","_LINK":"IA-REQ-002"},"18":{"MID":"c6cc5db815c441088ede4caa409c2690","UID":"IA-REQ-003","STATUS":"Active","TITLE":"Function-level traceability","STATEMENT":"Every public physics, control, solver, plotting, and scenario function SHALL contain a\nStrictDoc @relation marker.\n\nA function implementing several requirements SHALL contain separate relation markers\nfor every applicable requirement.\n\nInternal helper functions SHALL be traceable to the applicable implementation requirements.\n\nThe traceability system SHALL identify Requirement -> Python Function -> Test -> Notebook Scenario.\n","COMMENT":"CI greps @relation(UID, scope=function) in src/ironair and maps each implementation\nrequirement to at least one function.\n","_LINK":"IA-REQ-003"},"19":{"MID":"d3d9ca3f3c194f3a8f588d98360557fa","UID":"IA-REQ-004","STATUS":"Active","TITLE":"Bidirectional traceability","STATEMENT":"CI SHALL verify that every implementation requirement has an associated function,\nevery required function exists, every required function is covered by tests,\nevery documented scenario has a notebook, every required notebook executes successfully,\nall source-level requirement references resolve to valid StrictDoc UIDs, and every\nrequirements-to-source reference identifies an existing Python source element.\n","COMMENT":"tests/test_requirements_traceability.py fails the build on missing UIDs, missing\nfunctions, missing tests, or dangling file relations.\n","_LINK":"IA-REQ-004"},"20":{"MID":"7a04a3a4c71f4a5785a9649d60e77d97","UID":"IA-REQ-005","STATUS":"Active","TITLE":"Requirement verification","STATEMENT":"Every physical requirement SHALL specify acceptance criteria that can be objectively tested.\n\nCompliance SHALL be verified through unit tests, integration tests, conservation checks,\nnumerical convergence tests, and documented model validation.\n\nPassing software tests SHALL NOT be represented as physical validation against experimental hardware.\n","COMMENT":"Physical requirements include ACCEPTANCE_CRITERIA. Validation status is tracked separately\nfrom software verification in ironair.validation.\n","_LINK":"IA-REQ-005"},"21":{"MID":"b0b6744f5de54c219fcd7a5d5ac3ca77","UID":"IA-CON-001","STATUS":"Active","TITLE":"Constants module","STATEMENT":"Implement src/ironair/constants.py providing F_C_MOL, R_J_MOL_K, T_REF_K, P_REF_PA,\nM_FE_KG_MOL, M_O2_KG_MOL, M_H2O_KG_MOL, and M_KOH_KG_MOL.\n\nFundamental constants SHALL be immutable.\n","COMMENT":"from ironair import constants succeeds. Named constants match CODATA/IUPAC values\nwithin documented precision. Assignment to module constants raises an error or is\nrejected by typing/runtime freeze.\n","_LINK":"IA-CON-001"},"22":{"MID":"ab251d95aaa1434caf5472ed5825a86c","UID":"IA-CON-002","STATUS":"Active","TITLE":"Parameter definitions","STATEMENT":"Every component SHALL use explicit, typed parameter objects.\n\nParameters SHALL include name, value, SI unit, physical meaning, valid range,\nsource classification, literature reference when available, uncertainty when available,\nand calibration status.\n\nParameter categories SHALL distinguish fundamental constant, literature value,\nexperimental measurement, engineering design assumption, calibrated coefficient,\nand unverified placeholder.\n","COMMENT":"PhysicalParameter dataclass enforces required fields and rejects out-of-range values.\nUnverified placeholders are queryable via calibration_status.\n","_LINK":"IA-CON-002"},"23":{"MID":"50f23c9bfba746a38b88024fb2f39391","UID":"IA-CON-003","STATUS":"Active","TITLE":"Property models","STATEMENT":"Implement concentration- and temperature-dependent properties for KOH conductivity,\nKOH density, KOH viscosity, KOH heat capacity, KOH water activity, dissolved oxygen\nsolubility, oxygen diffusivity, gas-phase diffusivity, iron conductivity, thermal\nconductivity, reaction rate constants, and electrochemical exchange-current densities.\n\nProperty models SHALL enforce their valid domains.\n","COMMENT":"Property functions raise a domain error outside documented T and concentration ranges\nand return finite SI values inside the range.\n","_LINK":"IA-CON-003"},"24":{"MID":"f70967d503c144f482887ef9f6f798ea","UID":"IA-CHM-001","STATUS":"Active","TITLE":"Stoichiometric reaction network","STATEMENT":"Implement a common chemical reaction network.\n\nMathematical model:\n\n  dn/dt = S @ r + B @ q\n\nWhere S is the chemical stoichiometric matrix, r is the reaction-rate vector,\nB maps boundary flows to species inventories, and q is the boundary-flow vector.\n\nThe reaction network SHALL enforce elemental conservation.\n","COMMENT":"For every reaction column, elemental composition @ S[:, j] is numerically zero.\n","_LINK":"IA-CHM-001"},"25":{"MID":"cff0d79e6cef4a2d870accb296e5974b","UID":"IA-CHM-002","STATUS":"Active","TITLE":"Iron conversion","STATEMENT":"Implement Fe + 2OH- <-> Fe(OH)2 + 2e-.\n\nCalculate reaction rates from electrode kinetics and Faraday's law.\n","COMMENT":"Two electrons per iron atom. Faraday mapping r = i * A / (n * F) holds within solver tolerance.\n","_LINK":"IA-CHM-002"},"26":{"MID":"a01e77f107d14cfa8326382d49af6449","UID":"IA-CHM-003","STATUS":"Active","TITLE":"Magnetite formation","STATEMENT":"Implement configurable conversion between iron hydroxide and magnetite, including\nelectron transfer and correct stoichiometry.\n","COMMENT":"Default electrochemical path conserves Fe, O, H, and charge. A Schikorr chemical path\nmay be enabled without inventing extra electrons.\n","_LINK":"IA-CHM-003"},"27":{"MID":"5d967910ac9747308b0bfbc10a13c751","UID":"IA-CHM-004","STATUS":"Active","TITLE":"Oxygen reduction reaction","STATEMENT":"Implement O2 + 2H2O + 4e- -> 4OH-.\n","COMMENT":"Four electrons per O2. OH- production matches Faraday's law.\n","_LINK":"IA-CHM-004"},"28":{"MID":"c5e86eb89aec45f79c101bae706a37f3","UID":"IA-CHM-005","STATUS":"Active","TITLE":"Oxygen evolution reaction","STATEMENT":"Implement 4OH- -> O2 + 2H2O + 4e-.\n","COMMENT":"OER is the reverse four-electron oxygen couple of ORR with independent kinetics.\n","_LINK":"IA-CHM-005"},"29":{"MID":"21dcf9ab1db24548ad8b67d74adf26d8","UID":"IA-CHM-006","STATUS":"Active","TITLE":"Hydrogen evolution reaction","STATEMENT":"Implement 2H2O + 2e- -> H2 + 2OH-.\n","COMMENT":"Two electrons per H2. Rate increases with more negative iron overpotential.\n","_LINK":"IA-CHM-006"},"30":{"MID":"6546673aef58443fb7f1da74a439a7f2","UID":"IA-CHM-007","STATUS":"Active","TITLE":"Butler-Volmer kinetics","STATEMENT":"Implement nonlinear electrode kinetics with exchange-current density, transfer coefficients,\nlocal overpotential, temperature, species activities, electrode surface area, and\nreaction availability.\n","COMMENT":"Zero overpotential yields zero net Faradaic current at unit activities. Current is\nodd in overpotential for symmetric coefficients.\n","_LINK":"IA-CHM-007"},"31":{"MID":"1f58abe7a0844e17abdcfb081c41ffd4","UID":"IA-CHM-008","STATUS":"Active","TITLE":"Nernst potentials","STATEMENT":"Calculate equilibrium potentials using thermodynamically consistent activities and\nstandard electrode-potential references.\n","COMMENT":"Nernst potentials shift (RT/nF) ln(activity quotient) relative to documented E0.\n","_LINK":"IA-CHM-008"},"32":{"MID":"0d1510b823d241a486733b72a636444c","UID":"IA-CHM-009","STATUS":"Active","TITLE":"Reaction thermodynamics","STATEMENT":"Calculate Gibbs free energy, reaction enthalpy, reaction entropy, equilibrium cell\npotential, reversible reaction heat, and irreversible reaction heat.\n","COMMENT":"E_eq = -DeltaG / (n F). Irreversible heat is eta * i * A. Reversible heat uses T * DeltaS.\n","_LINK":"IA-CHM-009"},"33":{"MID":"abd9c8ab429b4665aa869ddc81fecf14","UID":"IA-CHM-010","STATUS":"Active","TITLE":"Chemistry conservation","STATEMENT":"The central chemistry module SHALL check iron atom conservation, oxygen atom conservation,\nhydrogen atom conservation, potassium conservation, carbon conservation, charge balance,\nelectron transfer, and reaction stoichiometry.\n","COMMENT":"Elemental residual norms are below 1e-12 relative to characteristic inventory for\nclosed-system reaction extents.\n","_LINK":"IA-CHM-010"},"34":{"MID":"3c0d84fb16884b6ab2371de3e8cc1ac3","UID":"IA-ODE-001","STATUS":"Active","TITLE":"Common component protocol","STATEMENT":"Every dynamic component SHALL implement rhs(self, t, y, inputs, context).\n\nThe RHS SHALL be deterministic for a fixed state, time, input, and parameter configuration.\n\nIt SHALL NOT modify component state through hidden side effects.\n","COMMENT":"Repeated rhs evaluations with identical arguments return identical arrays. Component\nparameter objects are unchanged after rhs.\n","_LINK":"IA-ODE-001"},"35":{"MID":"9301c86d88734044b85cf1e0f66790ff","UID":"IA-ODE-002","STATUS":"Active","TITLE":"State definitions","STATEMENT":"Each component SHALL publish named state metadata and a validated state vector layout.\n\nState arrays SHALL be NumPy arrays.\n","COMMENT":"y0 size matches len(state_specs). Units and names are unique per component.\n","_LINK":"IA-ODE-002"},"36":{"MID":"c901b9b8bfbf4b0cb3deb8e74de7be2d","UID":"IA-ODE-003","STATUS":"Active","TITLE":"Coupled solver","STATEMENT":"Implement ironair.simulation.CoupledSystem.\n\nThe solver SHALL assemble component states into one global state vector, maintain a\nstate-index map, resolve shared inputs and algebraic couplings, evaluate the coupled\nRHS, pass the assembled system to SciPy, detect numerical failures, and return state\ntrajectories and diagnostics.\n","COMMENT":"simulate() returns a SimulationResult with t, y, names, and solver diagnostics.\nFailure of solve_ivp is reported rather than silently truncated.\n","_LINK":"IA-ODE-003"},"37":{"MID":"d305bcfb24ab4bc19efb45737eda6d2b","UID":"IA-ODE-004","STATUS":"Active","TITLE":"Stiff solvers","STATEMENT":"The default integrated system SHALL use a stiff-capable solver, normally SciPy BDF or Radau.\n\nNonstiff component demonstrations MAY use RK45 or DOP853.\n","COMMENT":"CoupledSystem default method is BDF or Radau.\n","_LINK":"IA-ODE-004"},"38":{"MID":"a6518c78d56047b4b47595341831ffe3","UID":"IA-ODE-005","STATUS":"Active","TITLE":"Numerical robustness","STATEMENT":"The simulation SHALL include state-specific absolute tolerances, relative tolerances,\nJacobian sparsity, event detection, hybrid mode transitions, nonnegative inventory\nchecks, solver diagnostics, and energy and mass conservation residuals.\n","COMMENT":"SimulationResult exposes atol vector, events, conservation residuals, and solver status.\n","_LINK":"IA-ODE-005"},"39":{"MID":"07aa64831e6d45b3880409fa69729b0c","UID":"IA-ODE-006","STATUS":"Active","TITLE":"Multiscale execution","STATEMENT":"The system SHALL support millisecond, second, minute, hour, and multi-day simulation windows.\n\nDetailed electrochemical dynamics and long-duration grid dispatch SHALL be able to use\ndifferent model fidelity settings while sharing the same physical parameter definitions.\n","COMMENT":"The same ParameterSet can be passed to detailed and reduced-order components.\nt_span may be [0, 1e-3] or [0, 7*86400] without changing parameter objects.\n","_LINK":"IA-ODE-006"},"40":{"MID":"d30d1d11c5fc4ad1b60ab16f540d22d0","UID":"IA-NBK-001","STATUS":"Active","TITLE":"Notebook development environment","STATEMENT":"All notebooks SHALL be located in notebooks/.\n\nAll notebooks SHALL import numerical models from the installed ironair package.\n\nNo notebook SHALL contain a separate replacement implementation of a battery physics model.\n","COMMENT":"Notebook AST/source scan finds no duplicate rhs or stoichiometric matrix definitions.\n","_LINK":"IA-NBK-001"},"41":{"MID":"d08c848d32b24fb4a39cd9a5f518b51d","UID":"IA-NBK-002","STATUS":"Active","TITLE":"Seaborn visualization","STATEMENT":"All scenario notebooks SHALL use seaborn for the principal plots.\n\nMatplotlib MAY be used for figure management, multi-axis plots, annotations, and\nspecialized graphics.\n\nPlots SHALL include title, axis labels, physical units, legend where necessary,\nscenario identifier, and physical operating assumptions.\n","COMMENT":"Principal plotting helpers call seaborn and require title, xlabel, ylabel, and scenario_id.\n","_LINK":"IA-NBK-002"},"42":{"MID":"d99ea99769364a0b81a1d50597e51c04","UID":"IA-NBK-003","STATUS":"Active","TITLE":"Shared plotting API","STATEMENT":"Implement reusable plotting functions under ironair.plotting.\n\nPlotting functions SHALL accept structured simulation results or pandas DataFrames.\n","COMMENT":"from ironair import plotting succeeds and plot_states accepts SimulationResult or DataFrame.\n","_LINK":"IA-NBK-003"},"43":{"MID":"34d239d7ef934ec18d0da24b7eb58389","UID":"IA-NBK-004","STATUS":"Active","TITLE":"Chemical model demonstrations","STATEMENT":"Immediately after implementing the baseline chemistry, create notebooks demonstrating\niron oxidation, iron reduction, iron phase inventories, Butler-Volmer kinetics,\nNernst potential, ORR kinetics, OER kinetics, hydrogen evolution, oxygen limitation,\nKOH conductivity, electrolyte concentration, reaction heat, and mass and charge conservation.\n\nEach notebook SHALL call the actual associated Python component.\n","COMMENT":"Required chemistry notebooks exist under notebooks/chemistry and import ironair.chemistry.\n","_LINK":"IA-NBK-004"},"44":{"MID":"37a5b09b70a24770a551c4ef4eba80b3","UID":"IA-NBK-005","STATUS":"Active","TITLE":"Component demonstrations","STATEMENT":"Every component SHALL have a notebook or explicitly designated notebook section containing\ncomponent configuration, initial conditions, input stimulus, simulation execution,\ntime-domain plots, parameter sensitivity, conservation or physical validation results,\nand discussion of observed behavior.\n","COMMENT":"tests/test_notebook_inventory.py maps each component class to a notebook path.\n","_LINK":"IA-NBK-005"},"45":{"MID":"e1a762edd83f482cb37aac6cfd724b99","UID":"IA-NBK-006","STATUS":"Active","TITLE":"Full-system scenario demonstrations","STATEMENT":"The notebook suite SHALL cover all required operating scenarios described in Section 9.\n","COMMENT":"Every IA-NBK-007 through IA-NBK-016 scenario ID has a notebook and a Python scenario function.\n","_LINK":"IA-NBK-006"},"46":{"MID":"75e845c68cfd4a0eb70dfd98dae10690","UID":"IA-PLT-001","STATUS":"Active","TITLE":"Plot styling contract","STATEMENT":"Shared plotting functions SHALL apply a consistent seaborn theme and include physical units\non labeled axes.\n","COMMENT":"plotting helpers reject empty axis labels.\n","_LINK":"IA-PLT-001"},"47":{"MID":"99223f175baf469685cd80284f94a2a7","UID":"IA-TST-001","STATUS":"Active","TITLE":"Elemental conservation","STATEMENT":"The stoichiometric network SHALL conserve chemical elements for every reaction.\n","COMMENT":"max(abs(element_matrix @ S)) < 1e-12.\n","_LINK":"IA-TST-001"},"48":{"MID":"d0d8180ca8c143f78cc01d6ab057dd2f","UID":"IA-TST-002","STATUS":"Active","TITLE":"Charge conservation","STATEMENT":"Electrode currents, capacitive currents, and reaction rates SHALL obey conservation of charge.\n","COMMENT":"Sum of Faradaic, capacitive, and terminal currents is below 1e-9 A relative residual.\n","_LINK":"IA-TST-002"},"49":{"MID":"8c1e13ecda304c1a84f8a17be1d92d20","UID":"IA-TST-003","STATUS":"Active","TITLE":"Energy conservation","STATEMENT":"The coupled system SHALL account for electrical, chemical, thermal, and material-flow energy.\n","COMMENT":"Closed-system energy residual is reported and below documented tolerance for the adiabatic cell test.\n","_LINK":"IA-TST-003"},"50":{"MID":"4faef364e66843cab346df74f3437619","UID":"IA-TST-004","STATUS":"Active","TITLE":"Physical state validity","STATEMENT":"The simulation SHALL reject or explicitly report invalid physical states including negative\nspecies inventory, nonphysical porosity, invalid electrolyte volume, nonphysical absolute\ntemperature, invalid pressure, impossible oxygen consumption, and nonphysical cell voltage\nor current conditions.\n","COMMENT":"ironair.exceptions.InvalidPhysicalState is raised or recorded on invalid states.\n","_LINK":"IA-TST-004"},"51":{"MID":"caa57a0d36b9400dbc9951267b16aece","UID":"IA-TST-005","STATUS":"Active","TITLE":"Numerical convergence","STATEMENT":"The system SHALL include solver tolerance refinement tests and, for spatial models,\nmesh refinement tests.\n","COMMENT":"Halving rtol reduces trajectory error against a tight-tolerance reference.\n","_LINK":"IA-TST-005"},"52":{"MID":"27520cf8db7c4fa5b7f1fca40e212d06","UID":"IA-TST-006","STATUS":"Active","TITLE":"Model validation tracking","STATEMENT":"Software verification SHALL be distinguished from model validation.\n\nExperimental calibration and independent physical validation SHALL be separately tracked.\n","COMMENT":"Parameter source_class and validation.ValidationRecord never treat unit-test pass as\nhardware validation.\n","_LINK":"IA-TST-006"},"53":{"MID":"50ade2916b904b938c8a6444fdd88164","UID":"IA-TST-007","STATUS":"Active","TITLE":"Automated unit tests","STATEMENT":"Every exported physical calculation and dynamic component SHALL have automated pytest coverage.\n","COMMENT":"pytest coverage for src/ironair is at least 80 percent.\n","_LINK":"IA-TST-007"},"54":{"MID":"c954d9ae50114265a2f05bf6bc1baa7d","UID":"IA-TST-008","STATUS":"Active","TITLE":"Component integration tests","STATEMENT":"Every coupled component interface SHALL have integration tests verifying dimensions,\nunits, and conservation.\n","COMMENT":"CoupledSystem with a cell plus thermal node conserves charge and reports unit-consistent outputs.\n","_LINK":"IA-TST-008"},"55":{"MID":"1b05730586c54ba5a702b03a5498670f","UID":"IA-TST-009","STATUS":"Active","TITLE":"Notebook execution tests","STATEMENT":"Every mandatory notebook SHALL execute from a clean kernel without manual intervention.\n","COMMENT":"pytest marker notebook executes required notebooks via nbclient.\n","_LINK":"IA-TST-009"},"56":{"MID":"2ab2b3eb103848c1a85a99c9e8a9de9a","UID":"IA-TST-010","STATUS":"Active","TITLE":"Requirements coverage gate","STATEMENT":"CI SHALL fail when a required UID is missing, a requirement has no implementation function,\na required function is missing, a required equation is not tested, a notebook references\nan unavailable API, a mandatory notebook fails execution, or conservation acceptance\ncriteria fail.\n","COMMENT":"The traceability test enumerates these failure modes.\n","_LINK":"IA-TST-010"},"57":{"MID":"354ddd9385dd41f2a1a7aa9d4a2298eb","UID":"IA-TST-011","STATUS":"Active","TITLE":"Reproducibility","STATEMENT":"The simulation SHALL support deterministic parameter sets, recorded software versions,\nand fixed random seeds.\n","COMMENT":"SimulationResult.metadata includes ironair version and numpy seed. Sensor noise is\nseed-controlled.\n","_LINK":"IA-TST-011"},"58":{"MID":"e8405b7e9a194756a34f9c93a67557f6","UID":"IA-DOC-001","STATUS":"Active","TITLE":"Package documentation","STATEMENT":"The project SHALL publish architecture, API documentation, model limitations,\nrequirements coverage, and executable notebook demonstrations.\n","COMMENT":"README documents install, architecture, limitations, and that passing tests are not\nhardware validation.\n","_LINK":"IA-DOC-001"},"59":{"MID":"39fbaccdfd7b42d088cd8d815d3a42fd","UID":"IA-FE-001","STATUS":"Active","TITLE":"Iron electrode ODE","STATEMENT":"Module ironair.components.iron_electrode SHALL provide class IronElectrode.\n\nThe component SHALL dynamically model metallic iron, Fe(OH)2, Fe3O4, active surface\narea, passivation thickness, porosity, electrode temperature, and irreversible\nactive-material loss.\n\nThe RHS SHALL calculate iron phase derivatives from the shared reaction network.\n","COMMENT":"Discharge of Fe increases Fe(OH)2 using IA-CHM-002 stoichiometry. Temperature is a\ndynamic state. Passivation thickness is nonnegative.\n","_LINK":"IA-FE-001"},"60":{"MID":"99b92ed168b44e78b16ebac5d9dfe865","UID":"IA-HER-001","STATUS":"Active","TITLE":"Hydrogen evolution ODE","STATEMENT":"Module ironair.components.hydrogen SHALL provide class HydrogenEvolution.\n\nStates SHALL include hydrogen inventory and applicable interfacial or gas-transfer dynamics.\n\nThe component SHALL couple hydrogen generation to charging current and electrode potential.\n","COMMENT":"H2 inventory increases under negative iron overpotential. Open-circuit HER is smaller\nthan strong cathodic charging HER.\n","_LINK":"IA-HER-001"},"61":{"MID":"203b3ee5b3b34ee2bc397c9034379505","UID":"IA-ORR-001","STATUS":"Active","TITLE":"Oxygen reduction ODE","STATEMENT":"Module ironair.components.oxygen_reduction SHALL provide class OxygenReduction.\n\nStates SHALL include interfacial charge storage and oxygen availability where applicable.\n\nThe component SHALL calculate nonlinear ORR kinetics and oxygen consumption.\n","COMMENT":"ORR current is negative (cathodic) for eta < 0 versus the ORR Nernst potential.\nOxygen consumption matches Faraday's law for four-electron ORR.\n","_LINK":"IA-ORR-001"},"62":{"MID":"e53980b8eccf48f78b1d6bc60e1bf32c","UID":"IA-OER-001","STATUS":"Active","TITLE":"Oxygen evolution ODE","STATEMENT":"Module ironair.components.oxygen_evolution SHALL provide class OxygenEvolution.\n\nThe component SHALL calculate oxygen evolution, catalyst activity, and applicable\ndynamic electrode states.\n","COMMENT":"OER current is positive (anodic) for eta > 0 versus the OER Nernst potential.\n","_LINK":"IA-OER-001"},"63":{"MID":"1ab46f192d0347f0b30b7d3638cb2569","UID":"IA-GDL-001","STATUS":"Active","TITLE":"Gas diffusion ODE","STATEMENT":"Module ironair.components.gas_diffusion SHALL provide class GasDiffusionLayer.\n\nThe component SHALL calculate transient oxygen concentration profiles, effective\ndiffusion, pore saturation, flooding, and gas/liquid transport.\n","COMMENT":"A step decrease in boundary O2 mole fraction produces a delayed interior O2 decline.\nFlooding (saturation -> 1) reduces effective O2 diffusivity.\n","_LINK":"IA-GDL-001"},"64":{"MID":"e5be6ade0a5b4f6ead9101ef85c43540","UID":"IA-ELY-001","STATUS":"Active","TITLE":"Electrolyte ODE","STATEMENT":"Module ironair.components.electrolyte SHALL provide class Electrolyte.\n\nStates SHALL include water inventory, dissolved species, electrolyte temperature,\ncarbonation, and spatial concentration distributions where enabled.\n\nThe model SHALL include concentration-dependent KOH physical properties.\n","COMMENT":"Conductivity is computed from instantaneous KOH concentration and temperature via\nironair.properties. Carbonate accumulation consumes OH-.\n","_LINK":"IA-ELY-001"},"65":{"MID":"4264736518ba4b129f310e7034873b0e","UID":"IA-SEP-001","STATUS":"Active","TITLE":"Separator ODE","STATEMENT":"Module ironair.components.separator SHALL provide class Separator.\n\nThe model SHALL represent transient species transport, electrolyte saturation where\napplicable, degradation, and separator temperature.\n\nIonic resistance SHALL be calculated from the instantaneous physical state.\n","COMMENT":"R_ionic is algebraic in conductivity, thickness, area, and saturation. Temperature\nis dynamic.\n","_LINK":"IA-SEP-001"},"66":{"MID":"2eedd9e1fb064de8b78a6b823a718c6b","UID":"IA-COL-001","STATUS":"Active","TITLE":"Current collector ODE","STATEMENT":"Module ironair.components.current_collector SHALL provide class CurrentCollector.\n\nThe model SHALL include thermal dynamics and configurable long-term contact or\nresistance degradation.\n\nOhmic voltage loss SHALL be calculated algebraically.\n","COMMENT":"No fake lag state for resistance. V_ohm = I * R(T, degradation_state).\n","_LINK":"IA-COL-001"},"67":{"MID":"1991b2d6065e4371a97554a07ca84592","UID":"IA-CEL-001","STATUS":"Active","TITLE":"Complete cell ODE","STATEMENT":"Module ironair.components.cell SHALL provide class IronAirCell.\n\nThe cell SHALL couple iron electrode, air electrode, hydrogen evolution, electrolyte,\nseparator, gas diffusion, current collectors, and thermal dynamics.\n\nThe cell SHALL calculate instantaneous terminal voltage, current, power, SOC, and\navailable capacity.\n\nThe component SHALL solve coupled nonlinear electrochemical and electrical constraints.\n","COMMENT":"Cell rhs solves algebraic current/voltage consistency. Outputs include V, I, P, SOC.\n","_LINK":"IA-CEL-001"},"68":{"MID":"73d254c3641b483dbce45f3b63824052","UID":"IA-THM-001","STATUS":"Active","TITLE":"Thermal ODE","STATEMENT":"Module ironair.components.thermal SHALL provide class ThermalNetwork.\n\nStates SHALL include thermal energy or temperature at relevant physical nodes.\n\nThe model SHALL calculate conduction, convection, radiation, reaction heat, and cooling.\n","COMMENT":"Adiabatic isolated node with positive heat source increases temperature.\n","_LINK":"IA-THM-001"},"69":{"MID":"18f1170a2d12476d91a8700922ef0d4a","UID":"IA-AIR-001","STATUS":"Active","TITLE":"Air handling ODE","STATEMENT":"Module ironair.components.air_system SHALL provide class AirSystem.\n\nThe component SHALL include gas inventories, manifold pressure dynamics, oxygen\nconcentration, humidity, and airflow coupling.\n","COMMENT":"Manifold pressure rises when inlet mass flow exceeds outlet plus consumption.\n","_LINK":"IA-AIR-001"},"70":{"MID":"10ce357109654aad9ed6e19a95f95607","UID":"IA-AIR-002","STATUS":"Active","TITLE":"Fan ODE","STATEMENT":"Module ironair.components.fan SHALL provide class Fan.\n\nThe model SHALL include rotor speed dynamics and fan power consumption.\n","COMMENT":"Rotor speed is a dynamic state. Electrical power is an algebraic output from speed and torque.\n","_LINK":"IA-AIR-002"},"71":{"MID":"2846242e7ebf4043a6e66c5f8609b5a9","UID":"IA-FLD-001","STATUS":"Active","TITLE":"Electrolyte circulation ODE","STATEMENT":"Module ironair.components.electrolyte_flow SHALL provide class ElectrolyteFlow.\n\nThe component SHALL dynamically track flow, species transfer, pressure or hydraulic\nstorage where physically justified, and temperature.\n","COMMENT":"Species transport delay appears when using the detailed hydraulic mode.\n","_LINK":"IA-FLD-001"},"72":{"MID":"91da9d9834f1450291a90383bb446a0d","UID":"IA-FLD-002","STATUS":"Active","TITLE":"Pump ODE","STATEMENT":"Module ironair.components.pump SHALL provide class Pump.\n\nThe component SHALL model motor and hydraulic response, electrical input, and mechanical losses.\n","COMMENT":"Shaft speed is dynamic. Hydraulic power is less than electrical input by documented efficiency.\n","_LINK":"IA-FLD-002"},"73":{"MID":"a0f5631f292a49f18caebc1b1a762bf7","UID":"IA-FLD-003","STATUS":"Active","TITLE":"Reservoir ODE","STATEMENT":"Module ironair.components.reservoir SHALL provide class Reservoir.\n\nThe component SHALL model liquid inventory, chemical species inventories, temperature,\nand boundary flows.\n","COMMENT":"Mass balance: dM/dt equals inlet minus outlet minus leak.\n","_LINK":"IA-FLD-003"},"74":{"MID":"87ac458baf814ecead183c10f081967f","UID":"IA-FLD-004","STATUS":"Active","TITLE":"Valve ODE","STATEMENT":"Module ironair.components.valve SHALL provide class Valve.\n\nThe component SHALL model actuator response, valve position, and flow-dependent\nhydraulic characteristics.\n","COMMENT":"Position is a dynamic actuator state. Flow is algebraic in position and pressure drop.\n","_LINK":"IA-FLD-004"},"75":{"MID":"baa84fbdf1334d0cb40f104ac8951305","UID":"IA-FLD-005","STATUS":"Active","TITLE":"Piping ODE","STATEMENT":"Module ironair.components.piping SHALL provide class Pipe.\n\nThe component SHALL model transient fluid transport and temperature or species\nresidence-time dynamics when using the detailed hydraulic mode.\n","COMMENT":"Detailed mode has at least one transport delay state. Lumped mode is flagged reduced_order.\n","_LINK":"IA-FLD-005"},"76":{"MID":"6ff907a2398d46b78698a9ef8e1da6e6","UID":"IA-HEX-001","STATUS":"Active","TITLE":"Heat exchanger ODE","STATEMENT":"Module ironair.components.heat_exchanger SHALL provide class HeatExchanger.\n\nThe component SHALL represent thermal storage and dynamic heat transfer between fluid circuits.\n","COMMENT":"Two fluid temperatures approach each other under heat transfer with no external loss.\n","_LINK":"IA-HEX-001"},"77":{"MID":"2503339ae816471a92817023e7ee1bcb","UID":"IA-STK-001","STATUS":"Active","TITLE":"Stack ODE","STATEMENT":"Module ironair.components.stack SHALL provide class BatteryStack.\n\nThe component SHALL aggregate cell states while preserving cell-level variations and\nelectrical current conservation.\n","COMMENT":"Series stack current is identical through cells. Terminal voltage is the sum of cell voltages.\n","_LINK":"IA-STK-001"},"78":{"MID":"fb7e7d7a36ec49d5ba5fe0c54b3a10cb","UID":"IA-MOD-001","STATUS":"Active","TITLE":"Module ODE","STATEMENT":"Module ironair.components.module SHALL provide class BatteryModule.\n\nThe model SHALL include coupled stacks, shared fluid equipment, air equipment, and thermal states.\n","COMMENT":"Module assembles at least one stack plus shared thermal or fluid nodes.\n","_LINK":"IA-MOD-001"},"79":{"MID":"32c0b2b91ed54ee1bc3e05763eb9bbba","UID":"IA-ENC-001","STATUS":"Active","TITLE":"Enclosure ODE","STATEMENT":"Module ironair.components.enclosure SHALL provide class BatteryEnclosure.\n\nThe model SHALL include enclosure temperature, ventilation, auxiliary electrical loads,\nand enclosure-level gas inventories.\n","COMMENT":"Ventilation flow reduces enclosure H2 inventory. Auxiliary load is an algebraic electrical output.\n","_LINK":"IA-ENC-001"},"80":{"MID":"4adad99cb1b84fb2a8435c2abd14f817","UID":"IA-DC-001","STATUS":"Active","TITLE":"DC bus ODE","STATEMENT":"Module ironair.components.dc_bus SHALL provide class DCBus.\n\nThe component SHALL model DC link capacitor voltage and stored energy.\n","COMMENT":"C * V * dV/dt equals net electrical power into the capacitor.\n","_LINK":"IA-DC-001"},"81":{"MID":"a162668b9eb2442da280ccba6f117de4","UID":"IA-CNV-001","STATUS":"Active","TITLE":"DC/DC converter ODE","STATEMENT":"Module ironair.components.dc_converter SHALL provide class DCDCConverter.\n\nThe model SHALL include averaged inductor current, capacitor voltage, and converter losses.\n","COMMENT":"Averaged inductor current is a dynamic state. Losses increase output current demand.\n","_LINK":"IA-CNV-001"},"82":{"MID":"0d13586854d54c8d85875fb2654ae61f","UID":"IA-INV-001","STATUS":"Active","TITLE":"Inverter ODE","STATEMENT":"Module ironair.components.inverter SHALL provide class GridInverter.\n\nThe model SHALL include averaged electrical control dynamics, DC link interaction,\nand active/reactive power response.\n","COMMENT":"P and Q track references through explicit controller states, not prescribed algebraic jumps only.\n","_LINK":"IA-INV-001"},"83":{"MID":"9910e60567b04a23a1d4b0b272357b51","UID":"IA-TRF-001","STATUS":"Active","TITLE":"Transformer ODE","STATEMENT":"Module ironair.components.transformer SHALL provide class Transformer.\n\nThe component SHALL include electromagnetic dynamic states where detailed transient\nmodeling is enabled, along with winding and core thermal dynamics.\n","COMMENT":"Detailed mode includes flux or current states. Thermal states exist in both modes.\nPrescribed grid voltage is an input, not a transformer state.\n","_LINK":"IA-TRF-001"},"84":{"MID":"7927a419bef449fb9aee4a5b9d90998b","UID":"IA-GRD-001","STATUS":"Active","TITLE":"Grid interface ODE","STATEMENT":"Module ironair.components.grid SHALL provide class GridInterface.\n\nThe grid SHALL support dynamic voltage and frequency disturbances, network interface\nequations, and configurable external-grid dynamic models.\n\nA prescribed grid voltage or frequency SHALL be treated as an external input, not an\ninvented dynamic state.\n","COMMENT":"When voltage/frequency are prescribed, they appear in inputs. Optional swing-equation\nmode is explicitly identified.\n","_LINK":"IA-GRD-001"},"85":{"MID":"1d0fdf43d9b14efb837924f64d8b2918","UID":"IA-DEG-001","STATUS":"Active","TITLE":"Degradation ODE","STATEMENT":"Module ironair.components.degradation SHALL provide class Degradation.\n\nThe model SHALL represent irreversible material changes, catalyst decay, resistance\ngrowth, and active capacity loss.\n","COMMENT":"Degradation states are nondecreasing under positive aging rates. Capacity loss is irreversible.\n","_LINK":"IA-DEG-001"},"86":{"MID":"456cd77114a24eddac05f9793914ac32","UID":"IA-FLT-001","STATUS":"Active","TITLE":"Sensor ODE","STATEMENT":"Module ironair.components.sensors SHALL provide class DynamicSensor.\n\nThe model SHALL include finite response time, sensor drift, bias, and noise.\n","COMMENT":"First-order sensor lag is a dynamic state. Noise uses a documented random seed.\n","_LINK":"IA-FLT-001"},"87":{"MID":"11776de2631e4d0d8e816b190ec17669","UID":"IA-CTL-001","STATUS":"Active","TITLE":"Supervisory control dynamics","STATEMENT":"Module ironair.controls.supervisory SHALL provide class SupervisoryController.\n\nThe controller SHALL include explicit continuous controller states where applicable,\nas well as discrete operating modes.\n\nIt SHALL be implemented as a hybrid system with ODE dynamics and discrete transitions.\n","COMMENT":"Mode transitions are event-driven. PI or equivalent continuous states exist for current/power regulation.\n","_LINK":"IA-CTL-001"},"88":{"MID":"99bff3a425d84b719f2ba53ff5be4cb1","UID":"IA-EST-001","STATUS":"Active","TITLE":"State estimation","STATEMENT":"Module ironair.controls.estimation SHALL provide class BatteryStateEstimator.\n\nThe model SHALL estimate SOC, SOH, active iron inventory, and available charge/discharge power.\n\nIt SHALL not access the simulated plant's true hidden states during observer execution.\n","COMMENT":"Estimator rhs and update methods accept only measurements and previous estimates,\nnever plant.y hidden components.\n","_LINK":"IA-EST-001"},"89":{"MID":"140ad2894d80493387f93f0e9ab713fe","UID":"IA-NBK-007","STATUS":"Active","TITLE":"Charge scenarios","STATEMENT":"Required charge scenarios: constant-current, constant-power, constant-voltage,\ncharge tapering, partial charge, charge termination, overcharge protection,\nlow-temperature charging, high-temperature charging, charging with hydrogen\nevolution, and charging with limited electrolyte circulation.\n","COMMENT":"Each listed scenario has a unique IA-SCN-CHG-* ID, Python scenario function, notebook,\nand seaborn plots.\n","_LINK":"IA-NBK-007"},"90":{"MID":"4c497600ed494ce3bd82eac6e04d6c3e","UID":"IA-NBK-008","STATUS":"Active","TITLE":"Discharge scenarios","STATEMENT":"Required discharge scenarios: constant-current, constant-power, variable-load,\npartial discharge, deep discharge, oxygen-limited, thermal-limited, high-rate,\nlow-rate, and 100-hour discharge.\n","COMMENT":"Each listed scenario has a unique IA-SCN-DCH-* ID, Python scenario function, and notebook.\n","_LINK":"IA-NBK-008"},"91":{"MID":"0cf9a4c0c53b4ca8ab8f45ad88dcc46e","UID":"IA-NBK-009","STATUS":"Active","TITLE":"Transition scenarios","STATEMENT":"Required transition scenarios: charge to discharge, discharge to charge, rapid power\nreversal, rest period, voltage relaxation, repeated cycling, startup, shutdown, and\nrestart after protection trip.\n","COMMENT":"Each listed scenario has a unique IA-SCN-TRN-* ID, Python scenario function, and notebook.\n","_LINK":"IA-NBK-009"},"92":{"MID":"3975a2abbd2a41e3add3563f0606a9a8","UID":"IA-NBK-010","STATUS":"Active","TITLE":"Chemistry scenarios","STATEMENT":"Required chemistry scenarios: iron passivation, magnetite formation, hydrogen evolution,\noxygen starvation, carbonate accumulation, water depletion, electrolyte dilution,\nelectrolyte concentration increase, electrode aging, and catalyst degradation.\n","COMMENT":"Each listed scenario has a unique IA-SCN-CHM-* ID, Python scenario function, and notebook.\n","_LINK":"IA-NBK-010"},"93":{"MID":"108bce51e6494f7ba0bde8749f8e46ea","UID":"IA-NBK-011","STATUS":"Active","TITLE":"Environmental scenarios","STATEMENT":"Required environmental scenarios: cold start, hot start, ambient temperature cycling,\nhigh relative humidity, low relative humidity, high altitude, reduced atmospheric\noxygen, and thermal control failure.\n","COMMENT":"Each listed scenario has a unique IA-SCN-ENV-* ID, Python scenario function, and notebook.\n","_LINK":"IA-NBK-011"},"94":{"MID":"8c7483ce85ca4e408b68e2aba8867e80","UID":"IA-NBK-012","STATUS":"Active","TITLE":"Mechanical fault scenarios","STATEMENT":"Required mechanical fault scenarios: fan failure, pump failure, filter blockage,\nvalve failure, electrolyte leak, reservoir depletion, reduced circulation, heat\nexchanger failure, and ventilation failure.\n","COMMENT":"Each listed scenario has a unique IA-SCN-MCH-* ID, Python scenario function, and notebook.\n","_LINK":"IA-NBK-012"},"95":{"MID":"b47f9bd9d380487ba9ff899818820493","UID":"IA-NBK-013","STATUS":"Active","TITLE":"Electrical scenarios","STATEMENT":"Required electrical scenarios: cell short, cell open circuit, cell imbalance, stack\nmismatch, converter overload, DC bus undervoltage, DC bus overvoltage, inverter\ncurrent limit, and sensor failure.\n","COMMENT":"Each listed scenario has a unique IA-SCN-ELC-* ID, Python scenario function, and notebook.\n","_LINK":"IA-NBK-013"},"96":{"MID":"6b98430388c34d01b7334711f3332eef","UID":"IA-NBK-014","STATUS":"Active","TITLE":"Grid scenarios","STATEMENT":"Required grid scenarios: voltage sag, voltage swell, underfrequency, overfrequency,\nfrequency-watt response, volt-var response, grid disconnection, reconnection,\nride-through, and active/reactive power limits.\n","COMMENT":"Each listed scenario has a unique IA-SCN-GRD-* ID, Python scenario function, and notebook.\n","_LINK":"IA-NBK-014"},"97":{"MID":"ee3df314ef2845b9af6c33a444591b0c","UID":"IA-NBK-015","STATUS":"Active","TITLE":"Long-term scenarios","STATEMENT":"Required long-term scenarios: 100-hour discharge, multiple-day energy dispatch,\ncharge/discharge cycling, seasonal storage, calendar aging, cycle aging, capacity\nfade, efficiency degradation, and annual operating profile.\n","COMMENT":"Each listed scenario has a unique IA-SCN-LT-* ID, Python scenario function, and notebook.\n","_LINK":"IA-NBK-015"},"98":{"MID":"95e0825cfa014622bad90fe15cfc5edb","UID":"IA-NBK-016","STATUS":"Active","TITLE":"Characterization scenarios","STATEMENT":"Required characterization scenarios: current-voltage polarization curves,\ncharge/discharge voltage versus SOC, efficiency versus power, efficiency versus\ntemperature, SOC versus time, oxygen demand versus power, hydrogen generation versus\ncharge current, KOH concentration sweep, thermal response, parameter sensitivity,\nand uncertainty analysis.\n","COMMENT":"Each listed scenario has a unique IA-SCN-CHR-* ID, Python scenario function, and notebook.\n","_LINK":"IA-NBK-016"},"99":{"MID":"8a23c1ea1e8e4b269d439a4c30875a65","UID":"IA-SCN-CHG-CC","STATUS":"Active","TITLE":"Constant-current charging","STATEMENT":"Apply a constant charging current and record voltage, SOC, HER, and temperature.\n","COMMENT":"SOC increases. Terminal voltage rises. Current remains at the commanded charge value\nuntil a termination limit.\n","_LINK":"IA-SCN-CHG-CC"},"100":{"MID":"b4206a3fa721434c99e1a0b4d6292d85","UID":"IA-SCN-CHG-CP","STATUS":"Active","TITLE":"Constant-power charging","STATEMENT":"Apply a constant charging power command.\n","COMMENT":"Electrical power tracks the charge setpoint within solver tolerance until limits.\n","_LINK":"IA-SCN-CHG-CP"},"101":{"MID":"900d80e514ec4cababd93af8737c619c","UID":"IA-SCN-CHG-CV","STATUS":"Active","TITLE":"Constant-voltage charging","STATEMENT":"Hold a constant charge voltage after a current-limited approach.\n","COMMENT":"Charge current tapers as SOC increases under CV hold.\n","_LINK":"IA-SCN-CHG-CV"},"102":{"MID":"225b4dca2fda4e59b7b1ec28dd9cdbeb","UID":"IA-SCN-CHG-TAPER","STATUS":"Active","TITLE":"Charge tapering","STATEMENT":"Execute CC-CV tapering to a cutoff current.\n","COMMENT":"Simulation stops or flags complete when abs(I) falls below cutoff while voltage is held.\n","_LINK":"IA-SCN-CHG-TAPER"},"103":{"MID":"72d1d3242cde431c97c44435a6d2e5af","UID":"IA-SCN-CHG-PARTIAL","STATUS":"Active","TITLE":"Partial charge","STATEMENT":"Charge from an intermediate SOC to a higher intermediate SOC.\n","COMMENT":"Final SOC is between the start SOC and 1.0 and matches the scheduled stop.\n","_LINK":"IA-SCN-CHG-PARTIAL"},"104":{"MID":"5fbf5e3b96224ad08385c713cd2d3cd6","UID":"IA-SCN-CHG-TERM","STATUS":"Active","TITLE":"Charge termination","STATEMENT":"Terminate charge on voltage, current, SOC, or hydrogen-rate limits.\n","COMMENT":"Supervisory controller enters a rest or protection mode when a documented limit is crossed.\n","_LINK":"IA-SCN-CHG-TERM"},"105":{"MID":"3cd304b33e0d4246beb7a0e3b8a90625","UID":"IA-SCN-CHG-OVER","STATUS":"Active","TITLE":"Overcharge protection","STATEMENT":"Attempt overcharge and verify protection action.\n","COMMENT":"Current is removed or limited after the overcharge threshold. HER may rise before trip.\n","_LINK":"IA-SCN-CHG-OVER"},"106":{"MID":"01833668a96d4e6aade9759cf5a221b6","UID":"IA-SCN-CHG-LOWT","STATUS":"Active","TITLE":"Low-temperature charging","STATEMENT":"Charge at a cold ambient temperature within the property-model domain.\n","COMMENT":"Polarization is larger than the 298 K reference case. Solver remains stable.\n","_LINK":"IA-SCN-CHG-LOWT"},"107":{"MID":"7bfc1c706e27491799e8b7c93cebcfdf","UID":"IA-SCN-CHG-HIGHT","STATUS":"Active","TITLE":"High-temperature charging","STATEMENT":"Charge at an elevated ambient temperature within the property-model domain.\n","COMMENT":"HER rate is higher than the 298 K reference at the same current.\n","_LINK":"IA-SCN-CHG-HIGHT"},"108":{"MID":"b6348a90e33140f28e1c51d9563bed14","UID":"IA-SCN-CHG-HER","STATUS":"Active","TITLE":"Charging with hydrogen evolution","STATEMENT":"Charge under conditions that produce measurable HER.\n","COMMENT":"H2 inventory increases. Faradaic efficiency of iron conversion is less than 1.\n","_LINK":"IA-SCN-CHG-HER"},"109":{"MID":"a5268c2588104252a2db1fb958641192","UID":"IA-SCN-CHG-LOWFLOW","STATUS":"Active","TITLE":"Charging with limited electrolyte circulation","STATEMENT":"Charge with reduced or zero electrolyte pump flow.\n","COMMENT":"Local concentration gradients or voltage penalty exceed the circulating reference case.\n","_LINK":"IA-SCN-CHG-LOWFLOW"},"110":{"MID":"530416138ead4e0ba40a59ed1c20bf64","UID":"IA-SCN-DCH-CC","STATUS":"Active","TITLE":"Constant-current discharge","STATEMENT":"Apply a constant discharge current.\n","COMMENT":"SOC decreases. Voltage falls. Iron inventory is oxidized.\n","_LINK":"IA-SCN-DCH-CC"},"111":{"MID":"60fd0e1e80cc429e961c3b6a83fe25a6","UID":"IA-SCN-DCH-CP","STATUS":"Active","TITLE":"Constant-power discharge","STATEMENT":"Apply a constant discharge power command.\n","COMMENT":"Power tracks the discharge setpoint until a voltage or SOC limit.\n","_LINK":"IA-SCN-DCH-CP"},"112":{"MID":"7ea8d4d86bd84bf9b7787b04b71185d1","UID":"IA-SCN-DCH-VAR","STATUS":"Active","TITLE":"Variable-load discharge","STATEMENT":"Apply a time-varying discharge load profile.\n","COMMENT":"Current follows the scheduled profile within solver tolerance.\n","_LINK":"IA-SCN-DCH-VAR"},"113":{"MID":"79c516a7dafe4e589b79c3d57ae5558c","UID":"IA-SCN-DCH-PARTIAL","STATUS":"Active","TITLE":"Partial discharge","STATEMENT":"Discharge from a high SOC to an intermediate SOC.\n","COMMENT":"Final SOC matches the scheduled stop within tolerance.\n","_LINK":"IA-SCN-DCH-PARTIAL"},"114":{"MID":"483ee957a70840d7adfdc092869f0949","UID":"IA-SCN-DCH-DEEP","STATUS":"Active","TITLE":"Deep discharge","STATEMENT":"Discharge toward a low-SOC cutoff.\n","COMMENT":"Voltage declines and a low-SOC or low-voltage stop is reached without negative inventories.\n","_LINK":"IA-SCN-DCH-DEEP"},"115":{"MID":"cbaa3e90a42c40149045df7a8cff5353","UID":"IA-SCN-DCH-O2LIM","STATUS":"Active","TITLE":"Oxygen-limited discharge","STATEMENT":"Discharge with restricted oxygen supply.\n","COMMENT":"Available discharge current or voltage is lower than the air-rich reference.\n","_LINK":"IA-SCN-DCH-O2LIM"},"116":{"MID":"9924657412f9424ca9ad41a03f5e26a3","UID":"IA-SCN-DCH-THMLIM","STATUS":"Active","TITLE":"Thermal-limited discharge","STATEMENT":"Discharge until a thermal protection limit.\n","COMMENT":"Controller reduces current or trips when temperature exceeds the documented limit.\n","_LINK":"IA-SCN-DCH-THMLIM"},"117":{"MID":"e4fbd916b6e44284ac7a2110b8aca735","UID":"IA-SCN-DCH-HIGHRATE","STATUS":"Active","TITLE":"High-rate discharge","STATEMENT":"Discharge at a high C-rate relative to the design current.\n","COMMENT":"Overpotential and heat generation exceed the low-rate case.\n","_LINK":"IA-SCN-DCH-HIGHRATE"},"118":{"MID":"214be2a0e2ed414390f7c26fb83728bc","UID":"IA-SCN-DCH-LOWRATE","STATUS":"Active","TITLE":"Low-rate discharge","STATEMENT":"Discharge at a low C-rate.\n","COMMENT":"Voltage remains closer to Nernst than the high-rate case.\n","_LINK":"IA-SCN-DCH-LOWRATE"},"119":{"MID":"8d8ad10b652f4487bc215c34431e4404","UID":"IA-SCN-DCH-100H","STATUS":"Active","TITLE":"100-hour discharge","STATEMENT":"Discharge energy over a 100-hour window.\n","COMMENT":"Simulation spans 3.6e5 s and SOC declines monotonically under a positive discharge load.\n","_LINK":"IA-SCN-DCH-100H"},"120":{"MID":"d2a3da876c244cf08ac8c74658312bc9","UID":"IA-SCN-TRN-CHG2DCH","STATUS":"Active","TITLE":"Charge to discharge","STATEMENT":"Transition from charge to discharge.\n","COMMENT":"Current sign reverses. No nonphysical voltage spike is left unreported.\n","_LINK":"IA-SCN-TRN-CHG2DCH"},"121":{"MID":"88f66fac8d9a4d62819d40605a550c02","UID":"IA-SCN-TRN-DCH2CHG","STATUS":"Active","TITLE":"Discharge to charge","STATEMENT":"Transition from discharge to charge.\n","COMMENT":"Current sign reverses. SOC slope changes sign.\n","_LINK":"IA-SCN-TRN-DCH2CHG"},"122":{"MID":"34439929f3de499fa2312e6ce2375c8b","UID":"IA-SCN-TRN-REVERSAL","STATUS":"Active","TITLE":"Rapid power reversal","STATEMENT":"Reverse power on a short time scale relative to thermal states.\n","COMMENT":"Electrical states respond faster than thermal states. Solver remains stable.\n","_LINK":"IA-SCN-TRN-REVERSAL"},"123":{"MID":"c61370ce99ec44d9beb02906220990aa","UID":"IA-SCN-TRN-REST","STATUS":"Active","TITLE":"Rest period","STATEMENT":"Hold zero applied current after operation.\n","COMMENT":"Terminal current is ~0. Voltage relaxes toward equilibrium.\n","_LINK":"IA-SCN-TRN-REST"},"124":{"MID":"b5f4a449a4d446eeb7ccac224be3ede1","UID":"IA-SCN-TRN-RELAX","STATUS":"Active","TITLE":"Voltage relaxation","STATEMENT":"Record open-circuit voltage relaxation after current interruption.\n","COMMENT":"The absolute value of dV/dt decreases with time during rest.\n","_LINK":"IA-SCN-TRN-RELAX"},"125":{"MID":"b1c1f43bdb2042af948f8aa3d6686760","UID":"IA-SCN-TRN-CYCLE","STATUS":"Active","TITLE":"Repeated cycling","STATEMENT":"Apply repeated charge/discharge cycles.\n","COMMENT":"SOC oscillates. Optional degradation states are nondecreasing.\n","_LINK":"IA-SCN-TRN-CYCLE"},"126":{"MID":"e8faabfe503f4f7481ea64d100508e57","UID":"IA-SCN-TRN-STARTUP","STATUS":"Active","TITLE":"Startup","STATEMENT":"Start auxiliaries and electrical conversion from a rest state.\n","COMMENT":"Fan/pump speeds rise from near zero. DC bus voltage is established.\n","_LINK":"IA-SCN-TRN-STARTUP"},"127":{"MID":"7703b8696c394d07b38fa6f9c1797b49","UID":"IA-SCN-TRN-SHUTDOWN","STATUS":"Active","TITLE":"Shutdown","STATEMENT":"Command a controlled shutdown.\n","COMMENT":"Power command goes to zero and auxiliaries decelerate.\n","_LINK":"IA-SCN-TRN-SHUTDOWN"},"128":{"MID":"d7ecc5b72ea2406b9c67c0834bf2dad3","UID":"IA-SCN-TRN-RESTART","STATUS":"Active","TITLE":"Restart after protection trip","STATEMENT":"Clear a protection trip and resume operation.\n","COMMENT":"Mode returns from protection to a documented operating mode without hidden-state cheating.\n","_LINK":"IA-SCN-TRN-RESTART"},"129":{"MID":"fb7a44f9ccc740a7bec2641ddf153e3f","UID":"IA-SCN-CHM-PASS","STATUS":"Active","TITLE":"Iron passivation","STATEMENT":"Exercise passivation-thickness growth.\n","COMMENT":"Active area or exchange current declines as passivation thickness grows.\n","_LINK":"IA-SCN-CHM-PASS"},"130":{"MID":"3c651d189bc546a880ffa7543c1502ad","UID":"IA-SCN-CHM-MAG","STATUS":"Active","TITLE":"Magnetite formation","STATEMENT":"Convert Fe(OH)2 toward Fe3O4.\n","COMMENT":"Fe3O4 inventory increases and Fe(OH)2 decreases with conserved iron atoms.\n","_LINK":"IA-SCN-CHM-MAG"},"131":{"MID":"75ab1f44f6c44c1c96c7576681695b8f","UID":"IA-SCN-CHM-HER","STATUS":"Active","TITLE":"Hydrogen evolution chemistry scenario","STATEMENT":"Isolate HER kinetics versus potential.\n","COMMENT":"H2 production increases as iron potential becomes more negative.\n","_LINK":"IA-SCN-CHM-HER"},"132":{"MID":"048f65c738a74a2f98e46fb67c12419b","UID":"IA-SCN-CHM-O2STARV","STATUS":"Active","TITLE":"Oxygen starvation","STATEMENT":"Remove oxygen supply during discharge.\n","COMMENT":"ORR current collapses as O2 inventory approaches the documented floor.\n","_LINK":"IA-SCN-CHM-O2STARV"},"133":{"MID":"3802a080d12d439da0225be42c7eac4d","UID":"IA-SCN-CHM-CARB","STATUS":"Active","TITLE":"Carbonate accumulation","STATEMENT":"Expose electrolyte to CO2-bearing air.\n","COMMENT":"CO3 inventory increases and OH- inventory decreases.\n","_LINK":"IA-SCN-CHM-CARB"},"134":{"MID":"bc91054bca674014827ca55d2f35876c","UID":"IA-SCN-CHM-H2ODEP","STATUS":"Active","TITLE":"Water depletion","STATEMENT":"Operate with net water consumption or evaporation.\n","COMMENT":"Water inventory declines and is flagged before becoming negative.\n","_LINK":"IA-SCN-CHM-H2ODEP"},"135":{"MID":"65741cdc433f45b484108526e0cd00ae","UID":"IA-SCN-CHM-DILUTE","STATUS":"Active","TITLE":"Electrolyte dilution","STATEMENT":"Add water or reduce KOH inventory.\n","COMMENT":"KOH concentration and conductivity decrease.\n","_LINK":"IA-SCN-CHM-DILUTE"},"136":{"MID":"57a4a9acaea141589e8bcecf481e35ec","UID":"IA-SCN-CHM-CONC","STATUS":"Active","TITLE":"Electrolyte concentration increase","STATEMENT":"Remove water or add KOH.\n","COMMENT":"KOH concentration increases within the property-model domain.\n","_LINK":"IA-SCN-CHM-CONC"},"137":{"MID":"026fcdabf1294672991a90fdc6b3d560","UID":"IA-SCN-CHM-AGE","STATUS":"Active","TITLE":"Electrode aging","STATEMENT":"Apply aging rates to iron active material.\n","COMMENT":"Available capacity declines irreversibly.\n","_LINK":"IA-SCN-CHM-AGE"},"138":{"MID":"5d2e41eb33a942efa75343e2a2aaf0a1","UID":"IA-SCN-CHM-CATDEG","STATUS":"Active","TITLE":"Catalyst degradation","STATEMENT":"Decay ORR/OER catalyst activity.\n","COMMENT":"Exchange current densities decrease over time under the aging model.\n","_LINK":"IA-SCN-CHM-CATDEG"},"139":{"MID":"effc269db90e4d83a5189ab85fc39a89","UID":"IA-SCN-ENV-COLD","STATUS":"Active","TITLE":"Cold start","STATEMENT":"Start from a cold soaked initial temperature.\n","COMMENT":"Temperatures rise toward a warmer operating band under load or heaters if modeled.\n","_LINK":"IA-SCN-ENV-COLD"},"140":{"MID":"24fb7be8803d45beb22070b7d9d9fb8b","UID":"IA-SCN-ENV-HOT","STATUS":"Active","TITLE":"Hot start","STATEMENT":"Start from an elevated soaked temperature.\n","COMMENT":"Initial temperatures are above T_REF_K and remain within validity limits or are flagged.\n","_LINK":"IA-SCN-ENV-HOT"},"141":{"MID":"393b9dd63484444a85e05ec6887ac60d","UID":"IA-SCN-ENV-TAMP","STATUS":"Active","TITLE":"Ambient temperature cycling","STATEMENT":"Apply a cyclic ambient temperature boundary.\n","COMMENT":"Enclosure or cell temperature lags the ambient cycle.\n","_LINK":"IA-SCN-ENV-TAMP"},"142":{"MID":"dc908f9b3ef34ecba73338fb1c9384af","UID":"IA-SCN-ENV-HIGHRH","STATUS":"Active","TITLE":"High relative humidity","STATEMENT":"Supply high-humidity air.\n","COMMENT":"Gas humidity state increases relative to a dry-air case.\n","_LINK":"IA-SCN-ENV-HIGHRH"},"143":{"MID":"01eba1b7c6c447c6ba2336cf049b4ebd","UID":"IA-SCN-ENV-LOWRH","STATUS":"Active","TITLE":"Low relative humidity","STATEMENT":"Supply dry air.\n","COMMENT":"Electrolyte or GDL water is more depleted than the high-RH case.\n","_LINK":"IA-SCN-ENV-LOWRH"},"144":{"MID":"96a647ab4ac2406e887483a6cef7c8c7","UID":"IA-SCN-ENV-ALT","STATUS":"Active","TITLE":"High altitude","STATEMENT":"Reduce ambient pressure.\n","COMMENT":"Inlet oxygen partial pressure is lower than the sea-level reference.\n","_LINK":"IA-SCN-ENV-ALT"},"145":{"MID":"39e485ee2f4045c8bd196e243d653178","UID":"IA-SCN-ENV-LOWO2","STATUS":"Active","TITLE":"Reduced atmospheric oxygen","STATEMENT":"Reduce inlet O2 mole fraction.\n","COMMENT":"Discharge capability is reduced versus 0.21 mole fraction air.\n","_LINK":"IA-SCN-ENV-LOWO2"},"146":{"MID":"a24cb791127b459997437e19100c2701","UID":"IA-SCN-ENV-THMFAIL","STATUS":"Active","TITLE":"Thermal control failure","STATEMENT":"Disable cooling while load continues.\n","COMMENT":"Temperatures rise above the cooled reference. Protection may trip.\n","_LINK":"IA-SCN-ENV-THMFAIL"},"147":{"MID":"5c5c4e595d1b42a1aa42373fb47cec31","UID":"IA-SCN-MCH-FAN","STATUS":"Active","TITLE":"Fan failure","STATEMENT":"Force fan speed toward zero during operation.\n","COMMENT":"Airflow and O2 delivery fall. Discharge voltage penalty increases.\n","_LINK":"IA-SCN-MCH-FAN"},"148":{"MID":"7df70d17fccf4287a37be9d86d90df6f","UID":"IA-SCN-MCH-PUMP","STATUS":"Active","TITLE":"Pump failure","STATEMENT":"Force pump speed toward zero.\n","COMMENT":"Electrolyte circulation collapses.\n","_LINK":"IA-SCN-MCH-PUMP"},"149":{"MID":"0d140188e96147cab54a317cb88fe2b4","UID":"IA-SCN-MCH-FILTER","STATUS":"Active","TITLE":"Filter blockage","STATEMENT":"Increase air-path resistance.\n","COMMENT":"Airflow falls for the same fan command.\n","_LINK":"IA-SCN-MCH-FILTER"},"150":{"MID":"5ea3bebb164745a58a9a1d48a5cc6ba8","UID":"IA-SCN-MCH-VALVE","STATUS":"Active","TITLE":"Valve failure","STATEMENT":"Hold a valve at a failed position.\n","COMMENT":"Flow does not follow the commanded position.\n","_LINK":"IA-SCN-MCH-VALVE"},"151":{"MID":"da4bf8b76b58466cb99a08db827e6fce","UID":"IA-SCN-MCH-LEAK","STATUS":"Active","TITLE":"Electrolyte leak","STATEMENT":"Impose a leak mass-flow from the electrolyte circuit.\n","COMMENT":"Liquid inventory declines.\n","_LINK":"IA-SCN-MCH-LEAK"},"152":{"MID":"31172b9c0e9745b886033de813143c4e","UID":"IA-SCN-MCH-RESDEP","STATUS":"Active","TITLE":"Reservoir depletion","STATEMENT":"Operate until reservoir inventory approaches empty.\n","COMMENT":"An invalid or empty-reservoir condition is reported before negative mass.\n","_LINK":"IA-SCN-MCH-RESDEP"},"153":{"MID":"d247604bb0234ee6958897e7f2900104","UID":"IA-SCN-MCH-CIRC","STATUS":"Active","TITLE":"Reduced circulation","STATEMENT":"Command a reduced pump flow.\n","COMMENT":"Circulation flow is lower than the design case.\n","_LINK":"IA-SCN-MCH-CIRC"},"154":{"MID":"33ac33f7d8994fc0b74b3f28beb90120","UID":"IA-SCN-MCH-HEX","STATUS":"Active","TITLE":"Heat exchanger failure","STATEMENT":"Reduce heat-exchanger UA toward zero.\n","COMMENT":"Cooling heat transfer falls versus the healthy HEX case.\n","_LINK":"IA-SCN-MCH-HEX"},"155":{"MID":"5b51dd06b7234e159032ca1b628392a5","UID":"IA-SCN-MCH-VENT","STATUS":"Active","TITLE":"Ventilation failure","STATEMENT":"Disable enclosure ventilation.\n","COMMENT":"Enclosure gas inventories of H2 or heat rise relative to ventilated operation.\n","_LINK":"IA-SCN-MCH-VENT"},"156":{"MID":"ee01a5b160db4b95bbbd31c3c4bc1281","UID":"IA-SCN-ELC-SHORT","STATUS":"Active","TITLE":"Cell short","STATEMENT":"Impose a low-resistance cell short.\n","COMMENT":"Faulted cell voltage collapses and local heating increases.\n","_LINK":"IA-SCN-ELC-SHORT"},"157":{"MID":"2f45346654cf4acd8ad2ef322f403c64","UID":"IA-SCN-ELC-OC","STATUS":"Active","TITLE":"Cell open circuit","STATEMENT":"Open a cell in a series string.\n","COMMENT":"String current falls to ~0 or the open-cell path is flagged.\n","_LINK":"IA-SCN-ELC-OC"},"158":{"MID":"d87992e528b84ebf99a633e41bb55cdf","UID":"IA-SCN-ELC-IMBAL","STATUS":"Active","TITLE":"Cell imbalance","STATEMENT":"Initialize cells at different SOC.\n","COMMENT":"Cell voltages differ at the same string current.\n","_LINK":"IA-SCN-ELC-IMBAL"},"159":{"MID":"3391e3cae8bf4cdda0e41078ab6b5e07","UID":"IA-SCN-ELC-MISMATCH","STATUS":"Active","TITLE":"Stack mismatch","STATEMENT":"Operate paralleled or series stacks with mismatched capacity or resistance.\n","COMMENT":"Current sharing is unequal.\n","_LINK":"IA-SCN-ELC-MISMATCH"},"160":{"MID":"185cba8d57934a2d8a9fa33b703803c4","UID":"IA-SCN-ELC-CNVOVL","STATUS":"Active","TITLE":"Converter overload","STATEMENT":"Command converter current above rating.\n","COMMENT":"Current is limited to the rated value or a protection trip occurs.\n","_LINK":"IA-SCN-ELC-CNVOVL"},"161":{"MID":"c08f07a9af0c44d48d026c4e19b71198","UID":"IA-SCN-ELC-UV","STATUS":"Active","TITLE":"DC bus undervoltage","STATEMENT":"Drive DC-link voltage below the undervoltage threshold.\n","COMMENT":"Protection or limiter responds at the documented UV setpoint.\n","_LINK":"IA-SCN-ELC-UV"},"162":{"MID":"d12bb24d76bf46f3a9f53c4baf214f47","UID":"IA-SCN-ELC-OV","STATUS":"Active","TITLE":"DC bus overvoltage","STATEMENT":"Drive DC-link voltage above the overvoltage threshold.\n","COMMENT":"Protection or limiter responds at the documented OV setpoint.\n","_LINK":"IA-SCN-ELC-OV"},"163":{"MID":"0439529d9f834eca88144b0a03d130be","UID":"IA-SCN-ELC-ILIM","STATUS":"Active","TITLE":"Inverter current limit","STATEMENT":"Command inverter current above the limit.\n","COMMENT":"Delivered current does not exceed the limit except for documented transient overshoot.\n","_LINK":"IA-SCN-ELC-ILIM"},"164":{"MID":"0eb9fb7db40f40beabe9a104994dd70c","UID":"IA-SCN-ELC-SENSOR","STATUS":"Active","TITLE":"Sensor failure","STATEMENT":"Inject sensor bias, stuck, or noise faults.\n","COMMENT":"Estimator and controller use the failed measurement, not the hidden true plant state.\n","_LINK":"IA-SCN-ELC-SENSOR"},"165":{"MID":"6bed288e544f4c0eb6d146f83650052e","UID":"IA-SCN-GRD-SAG","STATUS":"Active","TITLE":"Grid voltage sag","STATEMENT":"Apply a grid voltage sag as an external input.\n","COMMENT":"Grid voltage is not a fabricated dynamic state when prescribed. Ride-through monitors record the event.\n","_LINK":"IA-SCN-GRD-SAG"},"166":{"MID":"1a5560ee81bf4d739b009fbd79c96183","UID":"IA-SCN-GRD-SWELL","STATUS":"Active","TITLE":"Grid voltage swell","STATEMENT":"Apply a grid voltage swell as an external input.\n","COMMENT":"Prescribed swell appears in inputs. Inverter reactive response follows the configured Q(V) curve if enabled.\n","_LINK":"IA-SCN-GRD-SWELL"},"167":{"MID":"fd2bb3bb91a1478bb21ed77b133ac554","UID":"IA-SCN-GRD-UF","STATUS":"Active","TITLE":"Underfrequency","STATEMENT":"Apply a grid underfrequency input.\n","COMMENT":"Frequency is an input unless swing-equation mode is explicitly enabled.\n","_LINK":"IA-SCN-GRD-UF"},"168":{"MID":"92bd0c242b9a46d6b7c84cc1ee14c54d","UID":"IA-SCN-GRD-OF","STATUS":"Active","TITLE":"Overfrequency","STATEMENT":"Apply a grid overfrequency input.\n","COMMENT":"Frequency-watt reduction of active power occurs when enabled.\n","_LINK":"IA-SCN-GRD-OF"},"169":{"MID":"329a8dc2dd4d45abab28ccc85f5660e2","UID":"IA-SCN-GRD-FW","STATUS":"Active","TITLE":"Frequency-watt response","STATEMENT":"Exercise P(f) droop.\n","COMMENT":"Active power decreases for overfrequency according to the configured droop.\n","_LINK":"IA-SCN-GRD-FW"},"170":{"MID":"77754289ff9a4f95901c92c17cdcb0c0","UID":"IA-SCN-GRD-VV","STATUS":"Active","TITLE":"Volt-var response","STATEMENT":"Exercise Q(V) droop.\n","COMMENT":"Reactive power sign follows the configured volt-var curve.\n","_LINK":"IA-SCN-GRD-VV"},"171":{"MID":"b7646f73bb784bd5b9375427834568a4","UID":"IA-SCN-GRD-DISC","STATUS":"Active","TITLE":"Grid disconnection","STATEMENT":"Open the grid interconnect.\n","COMMENT":"Grid current goes to ~0. Plant enters island or shutdown per controller mode.\n","_LINK":"IA-SCN-GRD-DISC"},"172":{"MID":"522a6d1166894af8a4998d35ad1f4f4d","UID":"IA-SCN-GRD-RECON","STATUS":"Active","TITLE":"Grid reconnection","STATEMENT":"Reconnect after a disconnect.\n","COMMENT":"Power exchange resumes only after documented sync/permission conditions.\n","_LINK":"IA-SCN-GRD-RECON"},"173":{"MID":"8b2c125aade743c596e38c51a1fb3709","UID":"IA-SCN-GRD-RT","STATUS":"Active","TITLE":"Ride-through","STATEMENT":"Remain connected through a documented disturbance envelope.\n","COMMENT":"Trip does not occur inside the configured ride-through region.\n","_LINK":"IA-SCN-GRD-RT"},"174":{"MID":"975c9a7e2f5142fa94375e3964486563","UID":"IA-SCN-GRD-PQ","STATUS":"Active","TITLE":"Active/reactive power limits","STATEMENT":"Command P and Q outside the capability curve.\n","COMMENT":"Delivered P/Q remain inside the capability region.\n","_LINK":"IA-SCN-GRD-PQ"},"175":{"MID":"6f03b9d033c446e3bc9d6bca7377f7c3","UID":"IA-SCN-LT-100H","STATUS":"Active","TITLE":"Long-term 100-hour discharge","STATEMENT":"Run the 100-hour discharge as a long-horizon scenario sharing cell parameters.\n","COMMENT":"Uses the same ParameterSet as short-horizon discharge, with fidelity settings documented.\n","_LINK":"IA-SCN-LT-100H"},"176":{"MID":"bf4eff2341d44292ad9e8cc7f4b53db7","UID":"IA-SCN-LT-DISPATCH","STATUS":"Active","TITLE":"Multiple-day energy dispatch","STATEMENT":"Follow a multi-day power schedule.\n","COMMENT":"SOC tracks charge and discharge windows in the schedule.\n","_LINK":"IA-SCN-LT-DISPATCH"},"177":{"MID":"d9e0ba55901642fdb36f22280b640f88","UID":"IA-SCN-LT-CYCLE","STATUS":"Active","TITLE":"Charge/discharge cycling long-term","STATEMENT":"Cycle for many days.\n","COMMENT":"Cycle count increases. Optional fade is nondecreasing.\n","_LINK":"IA-SCN-LT-CYCLE"},"178":{"MID":"43830bd6c9884ef1865837ce25703352","UID":"IA-SCN-LT-SEASON","STATUS":"Active","TITLE":"Seasonal storage","STATEMENT":"Hold energy over a seasonal horizon using reduced-order options as needed.\n","COMMENT":"Calendar aging can proceed while cycling rate is low. Reduced-order use is flagged.\n","_LINK":"IA-SCN-LT-SEASON"},"179":{"MID":"73f3bdca5b674d98a58857460841a5fe","UID":"IA-SCN-LT-CAL","STATUS":"Active","TITLE":"Calendar aging","STATEMENT":"Age at rest.\n","COMMENT":"Capacity or resistance changes with time at zero cycling current.\n","_LINK":"IA-SCN-LT-CAL"},"180":{"MID":"9ca9ce10792b49cca10023f92ac9082a","UID":"IA-SCN-LT-CYCAGE","STATUS":"Active","TITLE":"Cycle aging","STATEMENT":"Age under cycling.\n","COMMENT":"Fade rate exceeds the rest-only calendar case for the same elapsed time.\n","_LINK":"IA-SCN-LT-CYCAGE"},"181":{"MID":"46c2d6be822b413e9d3aa87c86e0cc55","UID":"IA-SCN-LT-FADE","STATUS":"Active","TITLE":"Capacity fade","STATEMENT":"Track available capacity versus time or throughput.\n","COMMENT":"Reported capacity is nonincreasing under the aging model.\n","_LINK":"IA-SCN-LT-FADE"},"182":{"MID":"b95047e89fcf410487b27ea3a2c3f58b","UID":"IA-SCN-LT-EFF","STATUS":"Active","TITLE":"Efficiency degradation","STATEMENT":"Track round-trip efficiency versus aging state.\n","COMMENT":"Efficiency declines as resistance grows.\n","_LINK":"IA-SCN-LT-EFF"},"183":{"MID":"2fc193a073ec4fa494cece07483d41ca","UID":"IA-SCN-LT-ANNUAL","STATUS":"Active","TITLE":"Annual operating profile","STATEMENT":"Execute a year-scale operating profile with documented fidelity.\n","COMMENT":"Scenario metadata records duration and fidelity setting. Parameters are shared with cell models.\n","_LINK":"IA-SCN-LT-ANNUAL"},"184":{"MID":"5b96ba2552cf4bf098d5a231718d48f7","UID":"IA-SCN-CHR-IV","STATUS":"Active","TITLE":"Current-voltage polarization","STATEMENT":"Sweep current and record voltage.\n","COMMENT":"Discharge branch voltage decreases with increasing current magnitude.\n","_LINK":"IA-SCN-CHR-IV"},"185":{"MID":"ce3934f3a5904d94a7e5854542f8067b","UID":"IA-SCN-CHR-VSOC","STATUS":"Active","TITLE":"Voltage versus SOC","STATEMENT":"Record charge and discharge voltage versus SOC.\n","COMMENT":"Charge voltage lies above discharge voltage at the same SOC for nonzero current.\n","_LINK":"IA-SCN-CHR-VSOC"},"186":{"MID":"43fe3ed80c0345dcad9e107c06fdcb75","UID":"IA-SCN-CHR-EFFP","STATUS":"Active","TITLE":"Efficiency versus power","STATEMENT":"Compute round-trip or one-way efficiency versus power.\n","COMMENT":"Efficiency is in (0, 1] for finite nonzero power.\n","_LINK":"IA-SCN-CHR-EFFP"},"187":{"MID":"573870b2e85a441e8ce7e865991c0adf","UID":"IA-SCN-CHR-EFFT","STATUS":"Active","TITLE":"Efficiency versus temperature","STATEMENT":"Sweep temperature and compute efficiency.\n","COMMENT":"Results stay within the property-model temperature domain.\n","_LINK":"IA-SCN-CHR-EFFT"},"188":{"MID":"bace3dabc061402a875c911a0b756909","UID":"IA-SCN-CHR-SOCT","STATUS":"Active","TITLE":"SOC versus time","STATEMENT":"Record SOC(t) for a documented load.\n","COMMENT":"SOC is in [0, 1] and consistent with Faraday accounting.\n","_LINK":"IA-SCN-CHR-SOCT"},"189":{"MID":"bb5c903fa5d246bd82067cf4c619d040","UID":"IA-SCN-CHR-O2P","STATUS":"Active","TITLE":"Oxygen demand versus power","STATEMENT":"Compute O2 molar demand versus discharge power.\n","COMMENT":"O2 demand increases with discharge power under ORR Faraday accounting.\n","_LINK":"IA-SCN-CHR-O2P"},"190":{"MID":"62986f723ef749e4885afccec862d7d0","UID":"IA-SCN-CHR-H2I","STATUS":"Active","TITLE":"Hydrogen generation versus charge current","STATEMENT":"Compute H2 rate versus charge current.\n","COMMENT":"H2 rate is nonnegative and increases with more severe charge polarization.\n","_LINK":"IA-SCN-CHR-H2I"},"191":{"MID":"97d0f3fbb01e4424bb6fbed5214f36fa","UID":"IA-SCN-CHR-KOH","STATUS":"Active","TITLE":"KOH concentration sweep","STATEMENT":"Sweep KOH concentration through the property domain.\n","COMMENT":"Conductivity and Nernst potentials vary with concentration. Domain errors are raised outside range.\n","_LINK":"IA-SCN-CHR-KOH"},"192":{"MID":"52122ae04bfc43e9950a4618c1266db3","UID":"IA-SCN-CHR-THM","STATUS":"Active","TITLE":"Thermal response characterization","STATEMENT":"Record temperature response to a load step.\n","COMMENT":"Temperature rises under dissipative load in an undercooled configuration.\n","_LINK":"IA-SCN-CHR-THM"},"193":{"MID":"347c102edd54421ca1413db5c7155a11","UID":"IA-SCN-CHR-SENS","STATUS":"Active","TITLE":"Parameter sensitivity","STATEMENT":"Perturb selected parameters and record output change.\n","COMMENT":"Sensitivity results identify which parameters were perturbed and their source_class.\n","_LINK":"IA-SCN-CHR-SENS"},"194":{"MID":"18493e30b46e4d2dbfae14c553e0b633","UID":"IA-SCN-CHR-UNC","STATUS":"Active","TITLE":"Uncertainty analysis","STATEMENT":"Propagate documented parameter uncertainties with a fixed random seed.\n","COMMENT":"Results are reproducible given the same seed and parameter uncertainty data.\n","_LINK":"IA-SCN-CHR-UNC"},"195":{"MID":"b16616e4c53c4a8bb73e8463b7f1edaa","UID":"IA-TD-001","STATUS":"Active","TITLE":"Package import test","STATEMENT":"Import ironair and the public subpackages listed in IA-SYS-001.\n","COMMENT":"No ImportError. __version__ is a nonempty string.\n","_LINK":"IA-TD-001"},"196":{"MID":"b81b19cdd8654231ba7f7da5385b5133","UID":"IA-TD-002","STATUS":"Active","TITLE":"Constants immutability test","STATEMENT":"Read F_C_MOL, R_J_MOL_K, T_REF_K, P_REF_PA, M_FE_KG_MOL, M_O2_KG_MOL, M_H2O_KG_MOL,\nand M_KOH_KG_MOL. Attempting assignment shall fail.\n","COMMENT":"Values match documented CODATA/IUPAC constants. Frozen assignment raises.\n","_LINK":"IA-TD-002"},"197":{"MID":"3f2a582327d44f808fa493ea83879d4f","UID":"IA-TD-003","STATUS":"Active","TITLE":"Elemental conservation test","STATEMENT":"For each column of S, compute the elemental residual E @ S[:, j].\n","COMMENT":"Absolute residual < 1e-12 for Fe, O, H, K, and C.\n","_LINK":"IA-TD-003"},"198":{"MID":"4f163725877f4fc4aafcb95ee7a5221b","UID":"IA-TD-004","STATUS":"Active","TITLE":"Butler-Volmer equilibrium test","STATEMENT":"Evaluate electrode current at zero overpotential with finite activities.\n","COMMENT":"Net Faradaic current is ~0. Symmetric coefficients produce an odd i(eta) function.\n","_LINK":"IA-TD-004"},"199":{"MID":"c1205eb4d78d47758861c057b290a27b","UID":"IA-TD-005","STATUS":"Active","TITLE":"RHS determinism test","STATEMENT":"Evaluate rhs twice with identical arguments.\n","COMMENT":"Arrays compare equal. Component parameter values are unchanged.\n","_LINK":"IA-TD-005"},"200":{"MID":"25941b9b7360418aafb8f66373382aad","UID":"IA-TD-006","STATUS":"Active","TITLE":"Traceability test","STATEMENT":"Parse reqs/**/*.sdoc UIDs and src/**/*.py @relation markers.\n","COMMENT":"Every @relation UID exists. Every implementation requirement listed in the\ntraceability map has a function marker.\n","_LINK":"IA-TD-006"},"201":{"MID":"1225e5cb831946479f6ef964b3d5d6b7","UID":"IA-TP-001","STATUS":"Active","TITLE":"Phase-gate testing","STATEMENT":"Each development phase SHALL have a passing pytest suite before the phase is complete.\n\nPhase 1: package import, constants, parameters, ODE protocol, StrictDoc UIDs.\nPhase 2: stoichiometric conservation, Butler-Volmer, Nernst, thermodynamics.\nPhase 3: chemistry notebooks execute.\nPhase 4+: component, coupled, scenario, and conservation tests as implemented.\n","COMMENT":"make test-phase-1 through make test-phase-2 fail closed when the corresponding tests fail.\n","_LINK":"IA-TP-001"},"202":{"MID":"11fa774d0a914cb0a0f0dc9c364a04b7","UID":"IA-TP-002","STATUS":"Active","TITLE":"Verification versus validation","STATEMENT":"Automated tests verify software against the SDRS. They SHALL NOT be labeled as\nexperimental hardware validation.\n","COMMENT":"README and ironair.validation state this distinction.\n","_LINK":"IA-TP-002"},"203":{"MID":"525b294a6f264e9ebd6c9243c3c7ec0b","UID":"IA-TP-003","STATUS":"Active","TITLE":"CI quality gates","STATEMENT":"CI SHALL run ruff, mypy, pytest with coverage, StrictDoc validation, and\nrequirements traceability.\n","COMMENT":".github/workflows/ci.yml implements these steps.\n","_LINK":"IA-TP-003"}};
